#!/bin/bash
# KADIMA forecast scoring-integrity release (PR #47, commit ef129a0c787e0f3686aa9f754b922186fd2d0b4a).
# Forecast-only: replaces kadima/hourly_forecast.py, nothing else. Run on EC2 as ubuntu, after 15:45 IST.
#   bash deploy_forecast_scoring_20261020.sh            # backup, install, restart, health check
#   bash deploy_forecast_scoring_20261020.sh --rollback # restore the backup and restart
set -u
ROOT=${KADIMA_ROOT:-$HOME/kadima-py}; DATA=${KADIMA_DATA_DIR:-/var/lib/kadima}
F=$ROOT/kadima/hourly_forecast.py
BASE=c702310cfcc7f98a61af334a6b428f08215d770e4a314d82e79a3eb0dee1e870
NEW=f4fb1b07ce4026557ca5a121f6ab3d745e1a4c76c7e6f7cc5806450bae936cd9
BAK=$F.bak-scoring-20261020
h() { sha256sum "$1" | cut -c1-64; }
health() {
  sleep 25
  systemctl is-active --quiet kadima || { echo "HEALTH FAIL: kadima not active"; return 1; }
  if journalctl -u kadima --since "-1 min" --no-pager | grep -q "Traceback"; then echo "HEALTH FAIL: traceback"; return 1; fi
  echo "health ok"; return 0
}
if [ "${1:-}" = "--rollback" ]; then
  [ "$(h $BAK)" = "$BASE" ] || { echo "ABORT: backup missing or wrong hash"; exit 1; }
  cp -p "$BAK" "$F" && sudo systemctl restart kadima && health; echo "live hash $(h $F | cut -c1-12) (base c702310cfcc7)"; exit
fi
echo "== 1. gates"
CUR=$(h $F); echo "live ${CUR:0:12} base ${BASE:0:12} release ${NEW:0:12}"
[ "$CUR" = "$NEW" ] && { echo "already installed"; exit 0; }
[ "$CUR" = "$BASE" ] || { echo "ABORT: live file is not the reviewed base; nothing changed"; exit 1; }
HM=$(TZ=Asia/Kolkata date +%H%M); DOW=$(TZ=Asia/Kolkata date +%u)
if [ "$DOW" -le 5 ] && [ "$HM" -ge 0900 ] && [ "$HM" -lt 1545 ]; then echo "ABORT: market hours (IST $HM); run after 15:45"; exit 1; fi
free -m | head -3
echo "== 15:25 / 15:29 candle closed flags (if closed=0, the last slot will show incomplete)"
sqlite3 -readonly $DATA/kadima.db "SELECT start_ts, interval, closed FROM candles WHERE token='99926000' AND interval IN (1,5) AND (start_ts LIKE '%T15:25:%' OR start_ts LIKE '%T15:29:%') ORDER BY start_ts DESC LIMIT 6;" || echo "(sqlite3 check skipped)"
read -r -p "No open positions and OK to restart kadima now? type YES: " OK; [ "$OK" = "YES" ] || { echo "stopped, nothing changed"; exit 1; }
echo "== 2. backup"
TS=$(date +%Y%m%d_%H%M%S); BD=$HOME/backups/forecast-scoring-$TS; mkdir -p $BD
cp -p "$F" "$BD/" && cp -p "$F" "$BAK"
sqlite3 $DATA/forecast.db ".backup '$BD/forecast.db'" || echo "(forecast.db backup skipped)"
sha256sum $BD/*
echo "== 3. install"
TMP=$F.new-20261020
echo '' | base64 -d > "$TMP"
[ "$(h $TMP)" = "$NEW" ] || { rm -f "$TMP"; echo "ABORT: payload hash mismatch"; exit 1; }
$ROOT/venv/bin/python -m py_compile "$TMP" || { rm -f "$TMP"; echo "ABORT: does not compile"; exit 1; }
mv "$TMP" "$F"; echo "installed $(h $F | cut -c1-12)"
echo "== 4. restart + health"
sudo systemctl restart kadima
if ! health; then echo "== AUTO ROLLBACK"; cp -p "$BAK" "$F"; sudo systemctl restart kadima; health; echo "rolled back to $(h $F | cut -c1-12)"; exit 1; fi
sqlite3 -readonly $DATA/forecast.db "PRAGMA table_info(hourly_forecast_points);" | grep -q actual_source && echo "column ok (created on first forecast connect if missing)" || echo "column not yet created (appears at first forecast tick)"
free -m | head -2
echo "DONE: release ${NEW:0:12} live. Backup in $BD. Rollback: bash $0 --rollback"
